    // 武器切换按钮
    touchControls.querySelectorAll('[data-action="weapon"]').forEach(btn => {
      const tap = (e) => {
        e.preventDefault(); btn.classList.add('active');
        const slot = parseInt(btn.dataset.slot);
        this.weapons.switchTo(slot === 1 ? 'usp' : 'ak47');
        setTimeout(() => btn.classList.remove('active'), 200);
      };
      const noop = () => {};
      bindPress(btn, tap, noop);
    });

    // 暂停按钮
    touchControls.querySelectorAll('[data-action="pause"]').forEach(btn => {
      const tap = (e) => {
        e.preventDefault(); btn.classList.add('active');
        if (this.state === 'playing') {
          this.state = 'paused';
          this.hud.showPause();
        }
        setTimeout(() => btn.classList.remove('active'), 200);
      };
      const noop = () => {};
      bindPress(btn, tap, noop);
    });
  }

  _requestLock() {
    try {
      const el = this.renderer.domElement;
      if (!el.requestPointerLock) return;
      const p = el.requestPointerLock();
      if (p && typeof p.catch === 'function') p.catch(() => {});
    } catch (e) { /* PointerLock 不可用（移动端/iframe），忽略 */ }
  }

  _resume() {
    if (this.state !== 'paused') return;
    this.hud.hidePause();
    this.state = 'playing';
    // PC 端尝试重新锁定鼠标；移动端无 PointerLock 则直接继续
    this._requestLock();
  }

